let lang = 'en';
export const getLang = () => lang;
export function setLang(l) {
  lang = D[l] ? l : 'en';
  document.documentElement.lang = lang;
  applyStatic();
}

export function t(key, p = {}) {
  let s = D[lang][key] ?? D.en[key] ?? key;
  for (const k in p) s = s.replaceAll(`{${k}}`, p[k]);
  return s;
}

// «1 card / 5 cards»; в русском три формы
export function plural(n) {
  if (lang === 'ru') {
    const m10 = n % 10, m100 = n % 100;
    if (m10 === 1 && m100 !== 11) return t('coll.card1', { n });
    if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return t('coll.card2', { n });
    return t('coll.cards', { n });
  }
  return t(n === 1 ? 'coll.card1' : 'coll.cards', { n });
}

export const dateLocale = () => ({ en: 'en-US', ru: 'ru-RU', es: 'es-ES', fr: 'fr-FR', de: 'de-DE', it: 'it-IT', pt: 'pt-BR', ja: 'ja-JP' })[lang];

// Статичный HTML: data-i18n (innerHTML), data-i18n-ph (placeholder), data-i18n-aria (aria-label)
export function applyStatic(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((el) => (el.innerHTML = t(el.dataset.i18n)));
  root.querySelectorAll('[data-i18n-ph]').forEach((el) => (el.placeholder = t(el.dataset.i18nPh)));
  root.querySelectorAll('[data-i18n-aria]').forEach((el) => el.setAttribute('aria-label', t(el.dataset.i18nAria)));
}
